"""The ``pennywise`` command-line interface."""

import argparse
import csv
import datetime
import json
import os
import sys
from typing import List, Optional

from .ledger import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_amount,
    parse_category,
    parse_date,
)

PROG = "pennywise"


class _ReadError(Exception):
    pass


def _date_arg(text: str) -> datetime.date:
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _read_text(path: str) -> str:
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as f:
                data = f.read()
    except OSError as exc:
        raise _ReadError(f"cannot read {path}: {exc.strerror or exc}") from None
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise _ReadError(f"cannot read {path}: not valid UTF-8 text") from None


def _load(path: str) -> List[Entry]:
    text = _read_text(path)
    try:
        return parse(text)
    except ParseError as exc:
        name = "<stdin>" if path == "-" else path
        raise ParseError(exc.line, f"{name}: {exc.reason}") from None


def _sorted(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same-day entries keep file order


def _entry_dict(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args) -> int:
    total = balance(_load(args.file))
    if args.json:
        print(json.dumps({"balance": format_amount(total)}))
    else:
        print(format_amount(total))
    return 0


def _cmd_summary(args) -> int:
    entries = _load(args.file)
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    names = sorted(groups)
    if args.json:
        print(json.dumps({n: format_amount(groups[n]) for n in names}))
    else:
        for n in names:
            print(f"{n}  {format_amount(groups[n])}")
    return 0


def _cmd_list(args) -> int:
    entries = filter_entries(
        _load(args.file), category=args.category, since=args.since, until=args.until
    )
    entries = _sorted(entries)
    if args.json:
        print(json.dumps([_entry_dict(e) for e in entries]))
    else:
        for e in entries:
            print(format_entry(e))
    return 0


def _cmd_export(args) -> int:
    entries = _sorted(_load(args.file))
    writer = csv.writer(sys.stdout, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return 0


def _cmd_add(args) -> int:
    path = args.file
    existing = b""
    if os.path.lexists(path):
        try:
            with open(path, "rb") as f:
                existing = f.read()
        except OSError as exc:
            raise _ReadError(f"cannot read {path}: {exc.strerror or exc}") from None

    # The line number the new entry will have once appended.
    text = existing.decode("utf-8", errors="replace")
    line_count = text.count("\n") + text.count("\r") - text.count("\r\n")
    ends_with_break = existing.endswith((b"\n", b"\r"))
    lineno = line_count + 1 if (not existing or ends_with_break) else line_count + 2

    note = args.note if args.note is not None else ""
    try:
        date = parse_date(args.date)
        category = parse_category(args.category)
        amount = parse_amount(args.amount)
        if "\n" in note or "\r" in note:
            raise ValueError("note must be on a single line")
        entry = Entry(date, category, amount, note.strip())
        line = format_entry(entry)
        if parse(line) != [entry]:  # make sure it reads back exactly
            raise ValueError("entry would not read back unchanged")
    except ValueError as exc:
        raise ParseError(lineno, f"{path}: {exc}") from None

    newline = b"\r\n" if b"\r\n" in existing else b"\n"
    data = line.encode("utf-8") + newline
    if existing and not ends_with_break:
        data = newline + data
    try:
        with open(path, "ab") as f:
            f.write(data)
    except OSError as exc:
        raise _ReadError(f"cannot write {path}: {exc.strerror or exc}") from None
    print(line)
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog=PROG, description="Tell you where the money in a plain-text ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all amounts")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=_cmd_balance)

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=_cmd_summary)

    p = sub.add_parser("list", help="print matching entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")
    p.set_defaults(func=_cmd_list)

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?")
    p.set_defaults(func=_cmd_add)

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")
    p.set_defaults(func=_cmd_export)

    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)  # exits with status 2 on a bad command line
    try:
        return args.func(args)
    except ParseError as exc:
        print(f"{PROG}: {exc}", file=sys.stderr)
        return 1
    except _ReadError as exc:
        print(f"{PROG}: {exc}", file=sys.stderr)
        return 2
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        return 0


if __name__ == "__main__":
    sys.exit(main())
